/// The row column of a language code
fn column(language: &str) -> usize {
    let code = language.get(..2).unwrap_or("en").to_ascii_lowercase();
    LANGUAGES.iter().position(|known| *known == code).unwrap_or(0)
}

/// The phrase for a key, English when unknown
pub fn text(key: &str, language: &str) -> &'static str {
    TABLE.iter().find(|(name, _)| *name == key).map_or("", |(_, row)| row[column(language)])
}

/// An alert's title and body
pub fn alert(key: &str, language: &str) -> (&'static str, &'static str) {
    let known = TABLE.iter().any(|(name, _)| name.strip_suffix(".title") == Some(key));
    let key = if known { key } else { "gnx.alert.test" };
    (text(&format!("{key}.title"), language), text(&format!("{key}.body"), language))
}
